CREATE OR REPLACE FUNCTION public.enforce_league_controls() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l leagues; BEGIN IF TG_TABLE_NAME<>'teams' THEN RETURN NEW; END IF; SELECT * INTO l FROM leagues WHERE id=NEW.league_id FOR UPDATE; IF NOT l.is_demo AND auth.uid() IS NOT NULL AND NOT l.invitations_enabled THEN RAISE EXCEPTION 'Invitations are paused by the commissioner'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.swap_lineup(tid uuid,active_slot int,bench_slot int) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE lid uuid;a uuid;b uuid;pos text;lk timestamptz; BEGIN SELECT league_id INTO lid FROM teams WHERE id=tid AND owner_id=auth.uid(); IF lid IS NULL OR active_slot NOT BETWEEN 1 AND 3 OR bench_slot NOT BETWEEN 4 AND 6 THEN RAISE EXCEPTION 'Invalid lineup change'; END IF; PERFORM 1 FROM leagues WHERE id=lid FOR UPDATE; SELECT lock_at INTO lk FROM leagues WHERE id=lid; IF lk IS NOT NULL AND now()>=lk THEN RAISE EXCEPTION 'Lineups are locked'; END IF; IF NOT (SELECT swaps_enabled FROM leagues WHERE id=lid) THEN RAISE EXCEPTION 'Lineup swaps are paused by the commissioner'; END IF; SELECT player_id INTO a FROM roster_slots WHERE team_id=tid AND slot=active_slot; SELECT player_id INTO b FROM roster_slots WHERE team_id=tid AND slot=bench_slot; SELECT position INTO pos FROM players WHERE id=b; IF b IS NULL OR (active_slot=1 AND pos<>'G') OR (active_slot=2 AND pos<>'F') THEN RAISE EXCEPTION 'Player is not eligible for this position'; END IF; UPDATE roster_slots SET player_id=NULL,projection=NULL WHERE team_id=tid AND slot IN (active_slot,bench_slot); UPDATE roster_slots SET player_id=b WHERE team_id=tid AND slot=active_slot; UPDATE roster_slots SET player_id=a WHERE team_id=tid AND slot=bench_slot; INSERT INTO league_activity(league_id,message) VALUES(lid,'Lineup updated'); END $$;
CREATE OR REPLACE FUNCTION public.claim_player(tid uuid,pid uuid,drop_slot int DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE lid uuid;s int;pos text;lk timestamptz;ds text; BEGIN SELECT league_id INTO lid FROM teams WHERE id=tid AND owner_id=auth.uid(); IF lid IS NULL THEN RAISE EXCEPTION 'You can only manage your own team'; END IF; SELECT lock_at,draft_status INTO lk,ds FROM leagues WHERE id=lid FOR UPDATE; IF NOT (SELECT pickups_enabled FROM leagues WHERE id=lid) THEN RAISE EXCEPTION 'Player pickups are paused by the commissioner'; END IF; IF ds<>'complete' THEN RAISE EXCEPTION 'Finish the draft before adding players'; END IF; IF lk IS NOT NULL AND now()>=lk THEN RAISE EXCEPTION 'Lineups are locked'; END IF; IF EXISTS(SELECT 1 FROM roster_slots WHERE league_id=lid AND player_id=pid) THEN RAISE EXCEPTION 'Player is already rostered'; END IF; SELECT position INTO pos FROM players WHERE id=pid; IF pos IS NULL THEN RAISE EXCEPTION 'Player not found'; END IF; IF drop_slot IS NOT NULL THEN s:=drop_slot; ELSE SELECT slot INTO s FROM roster_slots WHERE team_id=tid AND player_id IS NULL ORDER BY CASE WHEN slot>=4 THEN 0 ELSE 1 END,slot LIMIT 1; END IF; IF s IS NULL OR s NOT BETWEEN 1 AND 6 THEN RAISE EXCEPTION 'Choose a player to drop'; END IF; IF (s=1 AND pos<>'G') OR (s=2 AND pos<>'F') THEN RAISE EXCEPTION 'Choose a matching position or bench slot'; END IF; UPDATE roster_slots SET player_id=pid,projection=NULL WHERE team_id=tid AND slot=s; INSERT INTO league_activity(league_id,message) SELECT lid,'Added '||name FROM players WHERE id=pid; END $$;